WITH base AS (SELECT id, account_id, amount, merchant, is_flagged, TRIM(merchant) clean_merchant FROM transactions WHERE merchant IS NOT DISTINCT FROM 'Grab' AND txn_time > TIMESTAMP '2023-08-19 06:00:00'), valid AS (SELECT id, account_id, amount, is_flagged, clean_merchant, CAST(is_flagged AS INT) is_flagged_flag, COALESCE(merchant, 'NONE') merchant_clean FROM base WHERE merchant = 'Amazon'), filtered AS (SELECT *, CEIL(amount) amount_whole, amount + is_flagged_flag amount_plus_is_flagged_flag FROM valid WHERE amount < 1900), cleaned AS (SELECT id, account_id, amount, is_flagged, is_flagged_flag, merchant_clean, amount_whole, amount_plus_is_flagged_flag, CAST(is_flagged AS INT) is_flagged_flag_2, amount_whole + amount amount_whole_plus_amount FROM filtered WHERE amount_plus_is_flagged_flag >= 27), metrics AS (SELECT *, SUM(amount_plus_is_flagged_flag) OVER (PARTITION BY account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_amount_plus_is_flagged_flag, SUM(amount_plus_is_flagged_flag) OVER (PARTITION BY account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount_plus_is_flagged_flag, FIRST_VALUE(amount_whole) IGNORE NULLS OVER (PARTITION BY account_id ORDER BY is_flagged_flag_2 ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_amount_whole FROM cleaned WHERE is_flagged_flag_2 < 78) SELECT a.status, COUNT(*) AS cnt, MAX(s.running_amount_plus_is_flagged_flag) AS max_running_amount_plus_is_flagged_flag, MIN(s.amount_plus_is_flagged_flag) AS min_amount_plus_is_flagged_flag FROM metrics s JOIN accounts a ON s.account_id = a.id GROUP BY CUBE (a.status);
